"""Original Phase 2 standards, volume, plan and movement-alternative guidance."""
import sys
sys.path.insert(0, sys.argv[1] + '/scripts')
import copygen
from phase2_d4_sections import SECTIONS
OUT=sys.argv[2]
DATA={}
def base(slug,title,intro,question,answer,faq):
 return dict(title=title,description=intro[:155],eyebrow='Free tool · Strength',h1=title.replace('Free ',''),intro=intro,short_q=question,short_a=[answer],sections=SECTIONS[slug],coaches_h='Use the result with your clients',coaches=['Keep the calculation beside the completed training record. Review what the client actually performed, which equipment they used and how the session felt before changing the next prescription. A numerical result is easier to interpret when the exercise and execution remain consistent.', 'Discuss one practical next step rather than giving the client several competing targets. Put that instruction in the session and review the returned log. The useful outcome is a plan the client can follow and a record that helps you decide what to do next.'],pitch_key='workouts',pitch_h='Keep the plan and the completed work together',pitch='In Traiv you build workout plans, prescribe sets and repetitions, and review the work clients log in their app. Keep the next session alongside the history that explains it.',next=[('One-rep max calculator','/tools/one-rep-max-calculator'),('RPE calculator','/tools/rpe-calculator'),('Weekly training volume calculator','/tools/weekly-training-volume-calculator')],next_pitch='Use these tools to check a number, then review the full plan with your coach.',faq=faq,keep=[('Workout plans in Traiv','/features/plan-builder'),('All free tools','/tools')],close_h='Write the next session with the last one in view')
DATA['strength-standards-calculator']=base('strength-standards-calculator','Strength standards calculator','Compare a squat, bench press, deadlift or overhead press with published bodyweight-ratio benchmarks. See your current band and the next threshold in kg or lb.','How is my strength level calculated?','Divide your one-rep max by your body weight, then compare that ratio with the selected lift and sex category. At 180 lb body weight, a 275 lb squat is 1.53 times body weight: Novice in these sourced bands. The Intermediate threshold is 315 lb.',[
('What are strength standards?','They are reference benchmarks for a named lift and comparison group. They describe performance under stated assumptions, not health, personal worth or a universal training timeline.'),
('How does this calculator rank a lift?','It divides one-rep max by body weight and compares the result with Strength Level’s published aggregate ratio thresholds for the selected lift and sex category. It does not reproduce the publisher’s detailed weight-by-weight or age tables.'),
('What is a good squat, bench or deadlift for my body weight?','Choose the lift, enter your numbers and inspect the next threshold. A useful personal target also depends on experience, technique and the training you can consistently complete.'),
('Are these standards accurate for everyone?','No. The source describes a lifting community. These simplified bands do not adjust for age, disability, limb proportions, equipment or training history and are not general-population percentiles.'),
('Do I need to test a maximum?','No. You can enter an estimated one-rep max from a recent set, provided you label it as estimated. Formula uncertainty can move a result across a nearby band boundary.'),
('How should a coach use the result?','Use it as a conversation about the current lift and a realistic next step. Keep the exercise standard stable, inspect the session record and avoid promising a level within a fixed number of weeks.'),
('How much weight should I lift?','The next threshold is a reference, not your next working weight. Select a session load from the planned repetitions, effort and technique with your coach.'),
('Can I use an AI assistant to plan from the result?','Yes, for organising questions and a draft discussion. Include the source, unit, exercise, current maximum and training constraints. Ask it to distinguish a benchmark from a safe session prescription.')])
DATA['strength-standards-calculator']['method']='Strength Level aggregate bodyweight ratios, checked 15 November 2026. Simplified coaching reference; not age-adjusted norms.'
DATA['strength-standards-calculator']['sources']=[('Strength Level: squat standards','https://strengthlevel.com/strength-standards/squat/lb'),('Strength Level: bench press standards','https://strengthlevel.com/strength-standards/bench-press/lb'),('Strength Level: deadlift standards','https://strengthlevel.com/strength-standards/deadlift/lb'),('Strength Level: shoulder press standards','https://strengthlevel.com/strength-standards/shoulder-press/lb')]
DATA['strength-standards-calculator']['prompt']=dict(heading='Use this result with ChatGPT',when='After checking the lift, unit and source.',paste='Paste your result and recent training notes.',text='Help me discuss a strength goal with my coach. My lift is [lift], body weight [weight and unit], and tested or estimated 1RM [load]. The calculator uses Strength Level aggregate bodyweight ratios, not population percentiles. My current band is [band] and next threshold [load]. My available training days, equipment and recent sessions are [details]. Explain the gap without promising a deadline or treating the threshold as a working load. Ask for missing context before proposing changes.')
DATA['weekly-training-volume-calculator']=base('weekly-training-volume-calculator','Weekly training volume calculator','Add sets per session and sessions per week for each muscle group. Compare weekly totals with adjustable MEV, MAV and MRV landmarks before changing a training block.','How do I calculate weekly sets?','Multiply sets per session by sessions per week for each muscle group. Five chest sets across four sessions produce twenty weekly sets. The default landmarks are ten, fifteen and twenty, but they are editable planning assumptions, not personal recovery measurements.',[
('How do I calculate weekly training volume?','For the set-based measure here, multiply sets per session by sessions per week. If sessions differ, add the actual sets across those sessions and use an equivalent average or calculate the total separately.'),
('How many weekly sets should I use?','There is no single number that suits every client, muscle and training block. Start from work you can complete and recover from, then review performance and experience with your coach.'),
('What do MEV, MAV and MRV mean?','They refer to minimum effective, maximum adaptive and maximum recoverable volume in a coaching framework. The editable values are comparison landmarks; this tool does not measure those physiological limits.'),
('What counts as a hard set?','Use a consistent convention for purposeful working sets near your intended effort. Do not count easy rehearsal sets as though they were equivalent working sets. The exact convention should be agreed with your coach.'),
('Should indirect sets count?','Decide how to record overlapping work and apply that rule consistently. A row can involve the biceps without being equivalent to a direct curl set. This tool does not assign automatic fractional credit.'),
('When should I review weekly volume?','Review after changing a split, adding exercises, returning from a break or seeing repeated recovery or performance problems. Use several comparable sessions rather than one difficult day.')])
DATA['workout-plan-builder']=base('workout-plan-builder','Workout plan builder','Choose two to six training days, a goal and your experience level. Build a repeatable weekly split with exercises, sets and repetitions, then adapt it with your coach.','How does the workout plan builder work?','The builder selects a fixed split for your chosen frequency, applies goal-specific sets and repetitions, and adjusts the number of main-lift sets for experience. It is a transparent starting template, not an individual assessment or an AI-generated prescription.',[
('How do I build a workout plan from scratch?','Decide which days you can attend, choose a primary goal, select movements suited to your equipment and experience, then write sets, repetitions and a review rule. Use the generated split as a starting point.'),
('How many days should I train?','Choose a frequency you can repeat. This builder supports two to six days. More sessions are not automatically better, and an achievable schedule is more useful than an ambitious plan you regularly miss.'),
('Which split is best?','There is no universal best split. The builder uses full body for two or three days, upper/lower for four, a combined split for five and push/pull/legs for six. Review the resulting workload before using it.'),
('How many exercises should each session contain?','The template uses four to six exercises depending on the split and experience. The right number for your session also depends on setup time, rest, technique and the work you can complete well.'),
('How do I make the plan usable for clients?','Name the exact exercises, write clear set and repetition targets, explain effort and rest, and provide a way to log the completed work. Review that record before changing the next session.')])
DATA['injury-exercise-swap']=base('injury-exercise-swap','Injury exercise swap finder','Explore movement alternatives by exercise pattern and available equipment. Painful loading needs assessment; this tool does not diagnose an injury or prescribe rehabilitation.','How do I change a plan when an exercise hurts?','Stop the painful movement and establish whether assessment is needed before selecting a substitute. For a mild concern, this tool lists equipment-matched patterns to discuss with your coach. It withholds loaded options when you select painful loading or cannot load.',[
('How do I modify a plan around an injury?','Work within any clinician’s guidance, stop the painful movement and discuss whether another pattern is appropriate. Do not assume a different exercise is safe simply because it uses the same muscle.'),
('Is this medical or rehabilitation advice?','No. These are general movement alternatives, not a diagnosis, treatment, exercise clearance or recovery schedule. A clinician should assess an injury and guide rehabilitation when needed.'),
('When should I seek help instead of swapping exercises?','Seek assessment for painful loading, worsening symptoms or uncertainty about an injury. Sudden severe symptoms, new numbness or weakness, or inability to bear weight warrant urgent medical advice.'),
('Is this tool free?','Yes. You can explore the options without signing up. Keep the limitations in view and take any suggested movement to your coach or treating clinician before using it around an injury.')])
DATA['injury-exercise-swap']['disclaimer']='General information only. This tool does not diagnose injuries, prescribe rehabilitation or clear you to exercise. Stop a painful movement and seek appropriate medical advice. Use local urgent-care services for severe or concerning symptoms.'
for slug,data in DATA.items():
 copygen.write_checked(f'{OUT}/{slug}.tsx',data,{'strength-standards-calculator':2737,'weekly-training-volume-calculator':2728,'workout-plan-builder':2804,'injury-exercise-swap':1848}[slug])
